import{_ as o,o as u,c as q,ag as a}from"./chunks/framework.B5ULsuav.js";const d=JSON.parse('{"title":"五篇灵文-温养章全段","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/五篇灵文-温养章全段.md","filePath":"60-原文段落/五篇灵文-温养章全段.md","lastUpdated":1778155802000}'),e={name:"60-原文段落/五篇灵文-温养章全段.md"};function _(p,t,r,s,n,c){return u(),q("div",null,[...t[0]||(t[0]=[a('<h1 id="五篇灵文-温养章全段" tabindex="-1">五篇灵文-温养章全段 <a class="header-anchor" href="#五篇灵文-温养章全段" aria-label="Permalink to &quot;五篇灵文-温养章全段&quot;">​</a></h1><blockquote><p>来源：<a href="/liaokongjushi-wisdom/01-Raw-Sources/五篇灵文_了空居士_完整版">五篇灵文_了空居士_完整版</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>【原文】</strong></p><p>神守「黃房」，金胎自成。黃房乃乾之下、坤之上，十二時中，念茲在茲，含光藏耀，行住坐臥，綿綿若存，如雞抱卵，如龍養珠。抱元守一，先天元神元炁，刻刻相合，漸漸相化，但安神息，不運火而火自運。百日功靈，十月胎圓，陰魄自化，陽神出現，千日之後，溫養火足，剝盡群陰，體變純陽，嬰兒現象，身外有身，形如煙霞，神同太虛。隱，則形同於神；顯，則神同於氣，步日月而無影，貫金石而無礙。溫養三年之後，嬰兒老成，不可遠離，直至九年，與太虛同體，形神俱妙，與道合真。天地山川，有時崩壞，惟吾之道體，浩劫長存，潛伏人間，積功立行，提挈天地，把握陰陽，所以陰陽不能鋾鑄，天仙之道，斯乃畢矣。</p><hr><p><strong>【讲解】</strong></p><p>得药之后，就是温养。温就是保温，养就是我们来培养，也就是说要用文火，不可用心守，不可无意求，这种火候。</p><p>&quot;神守黃房&quot;，黃房是指哪里呢，对外来说指古代这些炼丹士住的房子，很多喜欢搞成黄色的，这里是比喻，是指中丹田。说到中丹田，你们千万不要以为专门是守膻中穴，不是！就是所谓的乾之下，坤之上，是意守整个体腔，你们也可以膻中穴这里为重点，但是要覆盖整个体腔。&quot;金胎自成&quot;，金，金刚不坏之仙胎，自己慢慢就会产生了，就会成就了。&quot;黃房乃乾之下、坤之上&quot;，这里就有说明，也就是上丹田之下，下丹田之上，其实是涵盖整个体腔，胸腔到腹腔。</p><p>&quot;十二時中&quot;，那你说，不用睡觉的吗？这是比喻，睡着了就睡着吧，俗话说日有所思，夜有所梦，有时侯半梦半醒之间——因为习惯返观你的身体了——也会自然返观，&quot;十二時中，念茲在茲&quot;，就是轻轻返观这个黄房，就是返观这个体腔。&quot;含光藏耀&quot;，就是精神内守，也不能守太紧。&quot;行住坐臥，綿綿若存&quot;，你在任何时候养成习惯都轻轻地好像似乎有点返观你的身体就对了，就是你在说话做事走路都可以养成这种轻轻返观身体的习惯，但是不能全神贯注，全神贯注反而是一种执着，而且你对外又不知道，那也很危险。&quot;如雞抱卵，如龍養珠&quot;，龍養珠就不知道，雞抱卵就知道，老母鸡要孵小鸡，翅膀抱着卵，有时侯也会跑出来吃东西，不能二十四小时抱着卵嘛。&quot;抱元守一&quot;，元，就是源头，一就是一个目标，我们小时候看老母鸡，你去那里看它，它也会咯咯叫，它也不是完全抱着蛋，其它什么也不管不知道，不是，它也知道的。</p><p>&quot;先天元神元炁&quot;，先天元神就是那种平静的心，似守非守，先天元气就是我们身上的能量到一定程度，你稍微一安静就自然有的，包括体内有气，体外也有场，&quot;刻刻相合&quot;，其实体内能量出现，你自然知道，精神和能量会自然结合在一起，&quot;漸漸相化&quot;，神中有气，气中有神，都一样的。&quot;但安神息&quot;，其实就是说只要你心平气和。&quot;不運火而火自運&quot;，这时候火候就恰到好处，自自然然的。</p><p>&quot;百日功靈&quot;，就是说如果有两三个月，一百天吧，就一定有变化。&quot;十月胎圓&quot;，十个月以上，元气就更加充满。所谓的结胎，其实就是体内的能量充满了。&quot;陰魄自化&quot;，阴魄就是妄想，包括那种打瞌睡，那种阴神的状态，&quot;陽神出現&quot;，陽神指两方面，一个是体内的能量从头顶冒出来，一个就是你的精神就变得非常好，不怎么会走神，不怎么会昏沉了。</p><p>&quot;溫養三年之後&quot;，出阳神可以训练，出阳神，出去回来再出去，可以训练个三年左右，&quot;嬰兒老成，不可遠離&quot;，阳神老成了，就要让它存在体内了。&quot;直至九年，與太虛同體&quot;，你就以上丹田功轻轻地返观全身，到一定程度，直至九年这个时间也是相对的，就是再过更长的时间，&quot;與太虛同體&quot;，这个阳神在体内跟你的肉身炼化了，你会感觉到阳神这个能量和你的肉身紧密结合在一起，你的肉体也觉得很明显虚无了，能够真正觉得和太虚空融为一体。&quot;形神俱妙&quot;是谁啊，修炼者，你的肉身和精神，就是气色非常好，精神状态也非常好，这就是形神俱妙。&quot;與道合真&quot;，道在哪里，&quot;有物混成&quot;（出自《道德经》），你就时时活在大道这个混元大气场里面了。</p>',13)])])}const l=o(e,[["render",_]]);export{d as __pageData,l as default};
